#include "BluetoothA2DPSink.h"

// Пины для энкодера KY-040
#define ENCODER_CLK 14
#define ENCODER_DT  12
#define ENCODER_SW  13

BluetoothA2DPSink a2dp_sink;

int current_volume = 60; // Начальная громкость (от 0 до 127)
int last_state_CLK;

void setup() {
    Serial.begin(115200);

    // Настройка пинов энкодера с подтяжкой к питанию
    pinMode(ENCODER_CLK, INPUT_PULLUP);
    pinMode(ENCODER_DT, INPUT_PULLUP);
    pinMode(ENCODER_SW, INPUT_PULLUP);

    // Считываем начальное состояние CLK
    last_state_CLK = digitalRead(ENCODER_CLK);

    // Настройка пинов I2S для MAX98357A
    i2s_pin_config_t my_pin_config = {
        .bck_io_num = 26,       // BCLK
        .ws_io_num = 25,        // LRC (WS)
        .data_out_num = 22,     // DIN
        .data_in_num = I2S_PIN_NO_CHANGE
    };
    a2dp_sink.set_pin_config(my_pin_config);

    // Устанавливаем стартовую громкость
    a2dp_sink.set_volume(current_volume);

    // Запуск Bluetooth
    a2dp_sink.start("ESP32_Bluetooth_Speaker");
    Serial.println("Колонка готова к подключению!");
}

void loop() {
    // 1. Обработка вращения энкодера (Громкость)
    int current_state_CLK = digitalRead(ENCODER_CLK);

    // Если состояние CLK изменилось, значит ручку повернули
    if (current_state_CLK != last_state_CLK && current_state_CLK == LOW) {
        // Проверяем направление вращения по состоянию DT
        if (digitalRead(ENCODER_DT) != current_state_CLK) {
            current_volume += 5; // Поворот по часовой стрелке -> громче
            if (current_volume > 127) current_volume = 127;
        } else {
            current_volume -= 5; // Поворот против часовой стрелки -> тише
            if (current_volume < 0) current_volume = 0;
        }

        // Применяем громкость в библиотеке A2DP
        a2dp_sink.set_volume(current_volume);

        Serial.print("Громкость: ");
        Serial.println(current_volume);
        delay(5); // Небольшая задержка от дребезга контактов
    }
    last_state_CLK = current_state_CLK;

    // 2. Обработка нажатия кнопки SW (Пауза / Плей)
    if (digitalRead(ENCODER_SW) == LOW) {
        delay(50); // Защита от дребезга контактов кнопки
        if (digitalRead(ENCODER_SW) == LOW) {
            // Переключаем состояние воспроизведения
            if (a2dp_sink.get_audio_state() == ESP_A2D_AUDIO_STATE_STARTED) {
                a2dp_sink.pause();
                Serial.println("Пауза");
            } else {
                a2dp_sink.play();
                Serial.println("Воспроизведение");
            }
            // Ждем, пока кнопку отпустят, чтобы не было повторных срабатываний
            while (digitalRead(ENCODER_SW) == LOW) { delay(10); }
        }
    }
}
